section.code:
// The block taxonomy, quoted from the normative schema (workflow-docs::model)
#[derive(Clone, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum Block {
    Section(Section), Prose(Vec<Inline>), Judgements(Judgements),
    Grammar(Vec<Production>), Rule(Rule), Definition(Definition),
    Diagram(Diagram), Code(CodeBlock), Example(Example),
    List(List), Table(Table), References(Vec<CiteKey>),
}
